data.output:
500				sawFinal = true
501				result.Status = decoded.Final.Status
502				result.Output = decoded.Final.FinalText
503				result.Duration = time.Duration(decoded.Final.DurationMS) * time.Millisecond
504				result.CostUSD = decoded.Final.CostUSD
505				result.Error = decoded.Final.Error
506				if decoded.Final.Usage != nil {
507					result.Tokens = cliTokenUsage{
508						Input:      derefInt(decoded.Final.Usage.InputTokens),
509						Output:     derefInt(decoded.Final.Usage.OutputTokens),
510						CacheRead:  derefInt(decoded.Final.Usage.CacheReadTokens),
511						CacheWrite: derefInt(decoded.Final.Usage.CacheWriteTokens),
512						Total:      derefInt(decoded.Final.Usage.TotalTokens),
513					}
514				}
515				if decoded.Final.RoutingActual != nil {
516					result.SelectedProvider = decoded.Final.RoutingActual.Provider
517					result.ResolvedModel = decoded.Final.RoutingActual.Model
518					result.Model = decoded.Final.RoutingActual.Model
519					result.AttemptedProviders = append([]string(nil), decoded.Final.RoutingActual.FallbackChainFired...)
520					if len(result.AttemptedProviders) > 1 {
521						result.FailoverCount = len(result.AttemptedProviders) - 1
522					} else {
523						result.FailoverCount = 0
524					}
525				}
526			}
527		}
528		if !sawFinal {
529			if ctx.Err() != nil {
530				result.Status = "cancelled"
531				result.Error = ctx.Err().Error()
532				return result, nil
533			}
534			return result, fmt.Errorf("service execution ended without final event")
535		}
536		return result, nil
537	}
