671	func normalizeRunSubcommand(args []string) (bool, []string) {
672		if len(args) == 0 {
673			return false, args
674		}
675		boolFlags := map[string]bool{
676			"allow-deprecated-model": true,
677			"json":                   true,
678			"list-models":            true,
679			"plan":                   true,
680			"version":                true,
681		}
682		valueFlags := map[string]bool{
683			"backend":   true,
684			"harness":   true,
685			"max-power": true,
686			"max-iter":  true,
687			"min-power": true,
688			"model":     true,
689			"model-ref": true,
690			"p":         true,
691			"preset":    true,
692			"provider":  true,
693			"reasoning": true,
694			"system":    true,
695			"work-dir":  true,
696		}
697	
698		for i := 0; i < len(args); i++ {
699			arg := args[i]
700			switch {
701			case arg == "run":
702				out := append([]string{}, args[:i]...)
703				out = append(out, args[i+1:]...)
704				return true, out
705			case strings.HasPrefix(arg, "-"):
706				flagName := strings.TrimLeft(arg, "-")
707				if boolFlags[flagName] {
708					continue
709				}
710				if valueFlags[flagName] && i+1 < len(args) {
711					i++
712				}
713			default:
714				return false, args
715			}
716		}
717	
718		return false, args
719	}
