721	// resolveProviderForRun selects and builds the provider for a run.
722	//
723	// Resolution order (matching SD-005):
724	//  1. If backendName is non-empty, resolve that backend pool.
725	//  2. Else if cfg.DefaultBackend is set and providerName is empty, resolve
726	//     the default backend pool.
727	//  3. Else fall back to direct provider selection (providerName or cfg.DefaultName).
728	type providerSelection struct {
729		Route             string
730		Provider          string
731		RequestedModel    string
732		RequestedModelRef string
733		ResolvedModelRef  string
734		ResolvedModel     string
735		ReasoningDefault  fizeau.Reasoning
736		NoStream          bool
737	}
738	
739	func resolveRunReasoning(cfg *agentConfig.Config, selection providerSelection, flagValue string) (fizeau.Reasoning, error) {
740		explicit := strings.TrimSpace(flagValue) != ""
741		if !explicit {
742			return selection.ReasoningDefault, nil
743		}
744		policy, err := reasoning.ParseString(flagValue)
745		if err != nil {
746			return "", err
747		}
748		if policy.Kind == reasoning.KindAuto {
749			if selection.ReasoningDefault != "" {
750				return selection.ReasoningDefault, nil
751			}
752			return fizeau.ReasoningAuto, nil
753		}
754		if policy.Kind == reasoning.KindTokens || policy.Value == reasoning.ReasoningMax {
755			maxTokens := lookupReasoningMaxTokens(cfg, selection.ResolvedModel)
756			if maxTokens > 0 {
757				if policy.Value == reasoning.ReasoningMax {
758					return fizeau.ReasoningTokens(maxTokens), nil
759				}
760				if policy.Tokens > maxTokens {
761					return "", fmt.Errorf("reasoning: token budget %d exceeds maximum %d for model %q", policy.Tokens, maxTokens, selection.ResolvedModel)
762				}
763			}
764		}
765		return fizeau.Reasoning(policy.Value), nil
766	}
