768	func lookupReasoningMaxTokens(cfg *agentConfig.Config, model string) int {
769		if model == "" {
770			return 0
771		}
772		catalog, err := cfg.LoadModelCatalog()
773		if err != nil || catalog == nil {
774			return 0
775		}
776		if entry, ok := catalog.LookupModel(model); ok {
777			return entry.ReasoningMaxTokens
778		}
779		return 0
780	}
