782	func resolveProviderForRun(cfg *agentConfig.Config, workDir, backendName, providerName string, overrides agentConfig.ProviderOverrides) (providerSelection, any, agentConfig.ProviderConfig, error) {
783		routeKey, routeModelRef, useLegacyBackend, err := resolveRouteTarget(cfg, backendName, providerName, overrides)
784		if err != nil {
785			return providerSelection{}, nil, agentConfig.ProviderConfig{}, err
786		}
787		if routeKey != "" {
788			selection, p, pc, err := buildRouteSelection(cfg, workDir, routeKey, routeModelRef, overrides.AllowDeprecated)
789			if err != nil {
790				return providerSelection{}, nil, agentConfig.ProviderConfig{}, err
791			}
792			return selection, p, pc, nil
793		}
794		if useLegacyBackend != "" {
795			counter, err := readAndIncrementRouteCounter(workDir, legacyRouteCounterName(useLegacyBackend))
796			if err != nil {
797				counter = 0
798			}
799			p, pc, resolved, err := cfg.ResolveBackend(useLegacyBackend, counter, overrides)
800			if err != nil {
801				return providerSelection{}, nil, agentConfig.ProviderConfig{}, err
802			}
803			selection := providerSelection{
804				Route:             useLegacyBackend,
805				ResolvedModel:     pc.Model,
806				RequestedModelRef: overrides.ModelRef,
807				NoStream:          true,
808			}
809			if bc, ok := cfg.GetBackend(useLegacyBackend); ok && len(bc.Providers) > 0 {
810				idx := selectBackendProviderIndex(bc.Strategy, counter, len(bc.Providers))
811				selection.Provider = bc.Providers[idx]
812			}
813			if resolved != nil {
814				selection.ResolvedModelRef = resolved.CanonicalID
815				selection.ReasoningDefault = fizeau.Reasoning(resolved.SurfacePolicy.ReasoningDefault)
816				if resolved.ConcreteModel != "" {
817					selection.ResolvedModel = resolved.ConcreteModel
818				}
819			}
820			return selection, p, pc, nil
821		}
822	
823		// Direct provider selection or exact model pin.
824		if providerName == "" {
825			providerName = cfg.DefaultName()
826		}
827		p, pc, resolved, err := cfg.BuildProviderWithOverrides(providerName, overrides)
828		if err != nil {
829			return providerSelection{}, nil, agentConfig.ProviderConfig{}, err
830		}
831		selection := providerSelection{
832			Route:             providerName,
833			Provider:          providerName,
834			RequestedModel:    overrides.Model,
835			RequestedModelRef: overrides.ModelRef,
836			ResolvedModel:     pc.Model,
837		}
838		if resolved != nil {
839			selection.ResolvedModelRef = resolved.CanonicalID
840			selection.ReasoningDefault = fizeau.Reasoning(resolved.SurfacePolicy.ReasoningDefault)
841			if resolved.ConcreteModel != "" {
842				selection.ResolvedModel = resolved.ConcreteModel
843			}
844		}
845		return selection, p, pc, nil
846	}
