848	func resolveRouteTarget(cfg *agentConfig.Config, backendName, providerName string, overrides agentConfig.ProviderOverrides) (routeKey string, routeModelRef string, legacyBackend string, err error) {
849		if providerName != "" {
850			return "", "", "", nil
851		}
852		if backendName != "" {
853			return "", "", backendName, nil
854		}
855		if overrides.Model != "" {
856			return overrides.Model, "", "", nil
857		}
858		if overrides.ModelRef != "" {
859			resolved, err := resolveCanonicalModelRef(cfg, overrides.ModelRef, overrides.AllowDeprecated)
860			if err != nil {
861				return "", "", "", err
862			}
863			return resolved.CanonicalID, overrides.ModelRef, "", nil
864		}
865		if cfg.Routing.DefaultModel != "" {
866			return cfg.Routing.DefaultModel, "", "", nil
867		}
868		if cfg.Routing.DefaultModelRef != "" {
869			resolved, err := resolveCanonicalModelRef(cfg, cfg.Routing.DefaultModelRef, true)
870			if err != nil {
871				return "", "", "", err
872			}
873			return resolved.CanonicalID, cfg.Routing.DefaultModelRef, "", nil
874		}
875		if cfg.DefaultBackend != "" {
876			return "", "", cfg.DefaultBackend, nil
877		}
878		return "", "", "", nil
879	}
