881	func buildRouteSelection(cfg *agentConfig.Config, workDir, routeKey, routeModelRef string, allowDeprecated bool) (providerSelection, any, agentConfig.ProviderConfig, error) {
882		plan, err := buildSmartRoutePlan(cfg, workDir, routeKey, routeModelRef, allowDeprecated, nil, nil)
883		if err != nil {
884			return providerSelection{}, nil, agentConfig.ProviderConfig{}, err
885		}
886		if len(plan.Order) == 0 {
887			return providerSelection{}, nil, agentConfig.ProviderConfig{}, fmt.Errorf("config: no route candidates available for %q", routeKey)
888		}
889		selected := plan.Candidates[plan.Order[0]]
890		if routeModelRef != "" && (selected.Model == "" || selected.Model == routeKey) {
891			resolvedPC, _, err := cfg.ResolveProviderConfig(selected.Provider, agentConfig.ProviderOverrides{ModelRef: routeModelRef, AllowDeprecated: allowDeprecated})
892			if err != nil {
893				return providerSelection{}, nil, agentConfig.ProviderConfig{}, err
894			}
895			selected.Model = resolvedPC.Model
896		}
897		p, pc, resolved, err := cfg.BuildProviderWithOverrides(selected.Provider, agentConfig.ProviderOverrides{
898			Model:           selected.Model,
899			ModelRef:        routeModelRef,
900			AllowDeprecated: allowDeprecated,
901		})
902		if err != nil {
903			return providerSelection{}, nil, agentConfig.ProviderConfig{}, err
904		}
905		pc.Model = selected.Model
906	
907		selection := providerSelection{
908			Route:             routeKey,
909			Provider:          selected.Provider,
910			RequestedModel:    routeKey,
911			RequestedModelRef: routeModelRef,
912			ResolvedModel:     pc.Model,
913			NoStream:          true,
914		}
915		if resolved != nil {
916			selection.ResolvedModelRef = resolved.CanonicalID
917			selection.ReasoningDefault = fizeau.Reasoning(resolved.SurfacePolicy.ReasoningDefault)
918			if resolved.ConcreteModel != "" {
919				selection.ResolvedModel = resolved.ConcreteModel
920			}
921		} else if routeModelRef != "" {
922			selection.ResolvedModelRef = routeKey
923		}
924		if selection.ReasoningDefault == "" && routeModelRef != "" {
925			if catalogResolved, err := resolveCanonicalModelRef(cfg, routeModelRef, allowDeprecated); err == nil {
926				selection.ReasoningDefault = fizeau.Reasoning(catalogResolved.SurfacePolicy.ReasoningDefault)
927				if selection.ResolvedModelRef == "" || selection.ResolvedModelRef == routeKey {
928					selection.ResolvedModelRef = catalogResolved.CanonicalID
929				}
930			}
931		}
932		return selection, p, pc, nil
933	}
