935	func resolveCanonicalModelRef(cfg *agentConfig.Config, ref string, allowDeprecated bool) (*modelcatalog.ResolvedTarget, error) {
936		catalog, err := cfg.LoadModelCatalog()
937		if err != nil {
938			return nil, err
939		}
940		surfaces := []modelcatalog.Surface{
941			modelcatalog.SurfaceAgentOpenAI,
942			modelcatalog.SurfaceAgentAnthropic,
943		}
944		var lastErr error
945		for _, surface := range surfaces {
946			resolved, err := catalog.Resolve(ref, modelcatalog.ResolveOptions{
947				Surface:         surface,
948				AllowDeprecated: allowDeprecated,
949			})
950			if err == nil {
951				return &resolved, nil
952			}
953			var missingSurfaceErr *modelcatalog.MissingSurfaceError
954			if errors.As(err, &missingSurfaceErr) {
955				lastErr = err
956				continue
957			}
958			return nil, err
959		}
960		if lastErr != nil {
961			return nil, lastErr
962		}
963		return nil, fmt.Errorf("config: cannot resolve model reference %q", ref)
964	}
