999			}

1000			return env
1001		}
1002		if cfg != nil {
1003			if dir := strings.TrimSpace(cfg.Skills.Dir); dir != "" {
1004				if dir == "-" {
1005					return ""
1006				}
1007				return dir
1008			}
1009		}
1010		return filepath.Join(workDir, ".fizeau", "skills")
