1074	// routeCounterMu serializes counter reads and writes within a process.
1075	var routeCounterMu sync.Mutex
1076	
1077	// readAndIncrementRouteCounter reads the current rotation counter for a route,
1078	// increments it, writes it back, and returns the value that was
1079	// read (i.e. the counter to use for this request).
1080	func readAndIncrementRouteCounter(workDir, routeName string) (int, error) {
1081		routeCounterMu.Lock()
1082		defer routeCounterMu.Unlock()
1083	
1084		path := routeStateFile(workDir, routeName)
1085	
1086		// Read existing counter; treat missing file as counter 0.
1087		var counter int
1088		if data, err := safefs.ReadFile(path); err == nil {
1089			if _, err := fmt.Sscanf(strings.TrimSpace(string(data)), "%d", &counter); err != nil {
1090				counter = 0
1091			}
1092		}
1093	
1094		// Write incremented counter.
1095		next := counter + 1
1096		if err := safefs.MkdirAll(filepath.Dir(path), 0o750); err != nil {
1097			return counter, err
1098		}
1099		if err := safefs.WriteFile(path, []byte(fmt.Sprintf("%d\n", next)), 0o600); err != nil {
1100			return counter, err
1101		}
1102	
1103		return counter, nil
1104	}
