586	// NeedsLegacyPassthrough reports whether argv should bypass Cobra traversal
587	// until the corresponding command path has native pflag definitions.
588	func NeedsLegacyPassthrough(args []string) bool {
589		valueFlags := map[string]bool{
590			"--backend":   true,
591			"--harness":   true,
592			"--max-power": true,
593			"--max-iter":  true,
594			"--min-power": true,
595			"--model":     true,
596			"--model-ref": true,
597			"--p":         true,
598			"-p":          true,
599			"--preset":    true,
600			"--provider":  true,
601			"--reasoning": true,
602			"--system":    true,
603			"--work-dir":  true,
604		}
605		subcommands := map[string]bool{}
606		for _, name := range mountedSubcommands() {
607			subcommands[name] = true
608		}
609		for i := 0; i < len(args); i++ {
610			arg := args[i]
611			if strings.HasPrefix(arg, "-") {
612				if valueFlags[arg] && i+1 < len(args) {
613					i++
614				}
615				continue
616			}
617			if arg == "run" {
618				return false
619			}
620			switch arg {
621			case "log", "replay", "usage", "providers", "models", "check", "route-status", "corpus", "import", "update":
622				return false
623			case "catalog":
624				if i+1 < len(args) {
625					switch args[i+1] {
626					case "show", "models", "observations", "check", "update", "update-pricing":
627						return false
628					}
629				}
630				return true
631			default:
632				return subcommands[arg] || arg != ""
633			}
634		}
635		return false
636	}
