// Package buildinfo derives version metadata from ldflags and runtime VCS info.
package buildinfo

import "runtime/debug"

// Info holds version metadata for the running binary.
type Info struct {
	Version string
	Commit  string
	Built   string
	Dirty   bool
}

// Read returns best-effort build metadata. ldflag values take precedence;
// runtime VCS info from debug.ReadBuildInfo() fills any empty fields, and
// always sets the Dirty flag from the VCS modified status.
func Read(ldflagVersion, ldflagCommit, ldflagBuilt string) Info {
	info := Info{
		Version: ldflagVersion,
		Commit:  ldflagCommit,
		Built:   ldflagBuilt,
	}
	bi, ok := debug.ReadBuildInfo()
	if !ok {
		return info
	}
	if (info.Version == "" || info.Version == "dev") &&
		bi.Main.Version != "" && bi.Main.Version != "(devel)" {
		info.Version = bi.Main.Version
	}
	for _, s := range bi.Settings {
		switch s.Key {
		case "vcs.revision":
			if info.Commit == "" && s.Value != "" {
				if len(s.Value) >= 8 {
					info.Commit = s.Value[:8]
				} else {
					info.Commit = s.Value
				}
			}
		case "vcs.time":
			if info.Built == "" {
				info.Built = s.Value
			}
		case "vcs.modified":
			info.Dirty = s.Value == "true"
		}
	}
	return info
}

